  ('d0000000-0000-4000-8000-000000000003', 'Burger étudiant à -15 %', '-15 %', 'restauration', 'Tous les burgers de la carte à prix réduit.', 'Sur place ou à emporter.', v_city, 'Kipé', 'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=900&q=70&auto=format&fit=crop', '2026-12-31', false, true, now() - interval '36 hours'),
