  ('d0000000-0000-4000-8000-000000000005', 'Réparation smartphone à -20 %', '-20 %', 'tech', 'Écran, batterie, connecteur : diagnostic gratuit.', 'Hors pièces premium. Garantie 1 mois.', v_city, 'Matam', 'https://images.unsplash.com/photo-1592899677977-9c10ca588bbd?w=900&q=70&auto=format&fit=crop', '2027-03-31', false, true, now() - interval '72 hours'),
