  ('d0000000-0000-4000-8000-000000000010', '-10 % en parapharmacie', '-10 %', 'sante', 'Soins, hygiène et produits de bien-être.', 'Hors médicaments sur ordonnance.', v_city, 'Camayenne', 'https://images.unsplash.com/photo-1505751172876-fa1923c5c528?w=900&q=70&auto=format&fit=crop', '2027-06-30', false, true, now() - interval '135 hours'),
