insert into public.jobs (company_name, partner_id, title, type, city_id, location, is_remote, compensation, description, skills, deadline, apply_email, is_demo, created_at) values
  ('NetZone Data', 'd0000000-0000-4000-8000-000000000012', 'Commercial étudiant (temps partiel)', 'job', v_city, 'Kaloum', false, '1 500 000 GNF/mois + commissions', 'Tu présentes nos forfaits internet sur les campus et dans les quartiers. Horaires flexibles compatibles avec les cours.', array['Communication','Négociation','Aisance à l''oral']::text[], '2026-11-30', null, true, now() - interval '0 hours'),
  ('Kaloum Digital', null, 'Community Manager junior', 'freelance', v_city, 'Kaloum', true, '800 000 GNF/mois', 'Animation des réseaux sociaux de 3 marques locales : planning éditorial, visuels simples, réponses aux messages.', array['Réseaux sociaux','Canva','Rédaction']::text[], '2026-11-15', null, true, now() - interval '7 hours'),
  ('Cabinet Nimba Conseil', null, 'Assistant administratif', 'job', v_city, 'Dixinn', false, '1 200 000 GNF/mois', 'Accueil, classement, saisie de documents et suivi des rendez-vous, 3 jours par semaine.', array['Word','Excel','Organisation']::text[], '2026-11-20', null, true, now() - interval '14 hours'),
  ('Fouta Agro', null, 'Stage marketing', 'stage', v_city, 'Matam', false, 'Indemnité de stage', 'Participe au lancement d''une gamme de jus locaux : études terrain, communication, événements.', array['Marketing','Études de marché','Créativité']::text[], '2026-12-15', null, true, now() - interval '21 hours'),
  ('Microfinance Espoir', null, 'Stage finance', 'stage', v_city, 'Kaloum', false, 'Indemnité de stage', 'Analyse de dossiers de crédit, suivi du portefeuille clients et reporting mensuel.', array['Comptabilité','Excel','Rigueur']::text[], '2026-12-01', null, true, now() - interval '28 hours'),
  ('Wakilé Tech', null, 'Développeur web junior', 'alternance', v_city, 'Kipé', false, '2 000 000 GNF/mois', 'Rejoins une startup qui construit des outils de paiement pour commerçants. Stack : React, Node.js.', array['JavaScript','React','Git']::text[], '2026-12-31', null, true, now() - interval '35 hours'),
  ('Yéla Mobilité', 'd0000000-0000-4000-8000-000000000009', 'Livreur à temps partiel', 'job', v_city, 'Ratoma', false, 'Rémunération à la course', 'Livraisons dans Ratoma et Dixinn en soirée et le week-end. Moto fournie.', array['Permis moto','Ponctualité']::text[], '2026-11-10', null, true, now() - interval '42 hours'),
  ('Saveurs de Kaloum', 'd0000000-0000-4000-8000-000000000001', 'Serveur / Serveuse le week-end', 'job', v_city, 'Kaloum', false, '600 000 GNF/mois', 'Service en salle le samedi et le dimanche, ambiance jeune et dynamique.', array['Service client','Sourire']::text[], '2026-11-05', null, true, now() - interval '49 hours'),
  ('Média Conakry Jeunes', null, 'Rédacteur web freelance', 'freelance', v_city, 'Conakry', true, '150 000 GNF/article', 'Rédaction d''articles sur la vie étudiante, l''emploi et l''entrepreneuriat en Guinée.', array['Rédaction','Orthographe','SEO']::text[], '2026-12-20', null, true, now() - interval '56 hours'),
  ('Association Lire Ensemble', null, 'Bénévole soutien scolaire', 'benevolat', v_city, 'Matoto', false, null, 'Aide aux devoirs pour des collégiens deux après-midis par semaine. Attestation de bénévolat fournie.', array['Pédagogie','Patience']::text[], '2026-12-31', null, true, now() - interval '63 hours'),
  ('Incubateur Kobi Lab', null, 'Concours d''innovation étudiante', 'concours', v_city, 'Conakry', false, 'Prix de 10 000 000 GNF', 'Présente ton projet d''entreprise devant un jury. Accompagnement de 6 mois pour les lauréats.', array['Entrepreneuriat','Pitch']::text[], '2026-12-10', null, true, now() - interval '70 hours'),
  ('Fondation Horizon Afrique', null, 'Bourse d''excellence Master', 'bourse', v_city, 'Conakry', false, 'Frais de scolarité + allocation', 'Bourse pour les étudiants en fin de Licence avec un excellent dossier académique.', array['Dossier académique','Lettre de motivation']::text[], '2027-01-15', null, true, now() - interval '77 hours'),
  ('Académie Code Conakry', 'd0000000-0000-4000-8000-000000000007', 'Formation certifiante Data Analyst', 'formation', v_city, 'Kipé', false, 'Tarif étudiant', '12 semaines pour apprendre Excel avancé, SQL et Power BI, avec projet final.', array['Logique','Excel']::text[], '2026-11-25', null, true, now() - interval '84 hours'),
  ('Groupe Sabou Logistique', null, 'Stage ressources humaines', 'stage', v_city, 'Matoto', false, 'Indemnité de stage', 'Recrutement, gestion administrative du personnel et organisation de formations internes.', array['RH','Communication','Excel']::text[], '2026-12-05', null, true, now() - interval '91 hours'),
  ('Institut Sondage Plus', null, 'Enquêteur terrain (étude de marché)', 'job', v_city, 'Conakry', false, '100 000 GNF/jour', 'Mission de 2 semaines : interroger des consommateurs sur tablette dans différents quartiers.', array['Aisance relationnelle','Soussou ou Poular apprécié']::text[], '2026-10-31', null, true, now() - interval '98 hours');
